const menu = window.ONAM_MENU;
const $ = s => document.querySelector(s);
const escapeHTML = text => String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let category='Favourites',limit=9;
const favouriteIds=['snack-masala-dosa','combo-kerala-sadya-red','curry-paneer-butter'];
if($('#favourites')) $('#favourites').innerHTML=favouriteIds.map((id,index)=>{const d=menu.find(x=>x.id===id);return `<article class="food-card"><div class="food-image"><button data-detail="${d.id}" aria-label="View ${escapeHTML(d.name)}"><img src="${d.image}" alt="${escapeHTML(d.name)}" loading="lazy"></button><span class="food-tag">${['THE GOLDEN CLASSIC','A KERALA FAVOURITE','COMFORT IN A BOWL'][index]}</span></div><div class="food-info"><div class="food-title"><h3>${index===1?'Kerala Sadya':d.name}</h3><span>₹${d.price}</span></div><p>${['Crisp, golden dosa with comforting potato masala.','A banana-leaf feast, with red rice at its heart.','Soft paneer in a rich, creamy tomato gravy.'][index]}</p><div class="food-bottom"><small><span class="veg-mark">●</span> PURE VEGETARIAN</small></div></div></article>`}).join('');
function renderMenu(){if(!$('#menu-grid'))return;const query=$('#menu-search').value.trim().toLowerCase();const filtered=[...menu].sort((a,b)=>Number(!!b.image)-Number(!!a.image)).filter(d=>(category==='All'||(category==='Favourites'?d.tags?.includes('Best Seller'):d.category===category))&&`${d.name} ${d.desc} ${d.tags||''}`.toLowerCase().includes(query));$('#menu-count').textContent=`${filtered.length} dishes to make your day`;$('#menu-grid').innerHTML=filtered.slice(0,limit).map(d=>`<article class="menu-item">${d.image?`<button class="menu-image-button" data-detail="${d.id}" aria-label="View ${escapeHTML(d.name)}"><img class="menu-thumb" src="${d.image}" alt="${escapeHTML(d.name)}" loading="lazy"></button>`:'<span class="no-photo" aria-hidden="true">✳</span>'}<div><button class="dish-name" data-detail="${d.id}"><h3>${escapeHTML(d.name)}</h3></button><p>${escapeHTML(d.desc)}</p><div class="food-bottom"><span class="price">₹${d.price}</span></div></div></article>`).join('')||'<div class="empty"><h3>No dishes found.</h3><p>Try another search or choose a different category.</p><button class="button outline" id="reset-search">Show the full menu</button></div>';$('#show-more').hidden=filtered.length<=limit;}
function selectCategory(value){category=value;limit=9;document.querySelectorAll('[data-category]').forEach(b=>{b.classList.toggle('active',b.dataset.category===value);b.setAttribute('aria-pressed',String(b.dataset.category===value));});renderMenu();}
document.querySelectorAll('[data-category]').forEach(b=>b.addEventListener('click',()=>selectCategory(b.dataset.category)));
$('#menu-search')?.addEventListener('input',()=>{limit=9;if($('#menu-search').value&&category==='Favourites')selectCategory('All');else renderMenu();});
$('#show-more')?.addEventListener('click',()=>{limit+=12;renderMenu();});
$('#drinks-link')?.addEventListener('click',()=>{selectCategory('Beverages');$('#menu-search').value='';renderMenu();$('#menu').scrollIntoView({behavior:'smooth'});});
function openDish(id){const d=menu.find(x=>x.id===id);if(!d)return;$('#dish-content').innerHTML=`${d.image?`<img src="${d.image}" alt="${escapeHTML(d.name)}">`:''}<div class="dish-body"><div class="eyebrow"><span class="veg-mark">●</span> ${d.category.toUpperCase()}</div><h2>${escapeHTML(d.name)}</h2><p>${escapeHTML(d.desc)}</p><p style="font-size:11px;margin-top:12px">Dietary requirements? Please check ingredients with the restaurant when ordering.</p><p class="price">₹${d.price}</p><a class="button" href="https://order.onamveg.in/">Explore online ordering ↗</a></div>`;$('#dish-dialog').showModal();}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.detail)openDish(b.dataset.detail);if(b.dataset.close)$('#'+b.dataset.close).close();if(b.id==='reset-search'){$('#menu-search').value='';selectCategory('All');}});

document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
$('#year').textContent=new Date().getFullYear();renderMenu();

const requestedCategory=new URLSearchParams(location.search).get('category');if($('#menu-grid')&&['Combos','Rice','Curries','Breads','Snacks','Beverages','All'].includes(requestedCategory))selectCategory(requestedCategory);
